import nanosurf

# Load application
spm = nanosurf.SPM()
application = spm.application

# Try to get the last saved image path using different methods
try:
    # Method 1: Direct call
    image_path = application.GetLastSavedImagePath()
    print(f"Image path (method 1): {image_path}")
except Exception as e:
    print(f"Method 1 failed: {e}")

try:
    # Method 2: Check if there's a property
    if hasattr(application, 'LastSavedImagePath'):
        image_path = application.LastSavedImagePath
        print(f"Image path (method 2): {image_path}")
except Exception as e:
    print(f"Method 2 failed: {e}")

try:
    # Method 3: Get gallery history
    if hasattr(application, 'GetGalleryHistoryFilenameMask'):
        mask = application.GetGalleryHistoryFilenameMask()
        print(f"Filename mask: {mask}")
except Exception as e:
    print(f"Method 3 failed: {e}")

# List available methods and properties
print("\nAvailable application methods and properties:")
for attr in dir(application):
    if not attr.startswith('_') and ('path' in attr.lower() or 'file' in attr.lower() or 'image' in attr.lower() or 'save' in attr.lower()):
        print(f"  - {attr}")

del spm
